import{_ as o,o as e,c as a,ag as r}from"./chunks/framework.CAXxHpAX.js";const i=JSON.parse('{"title":"金刚经8分-佛法即非佛法","description":"","frontmatter":{},"headers":[],"relativePath":"60-原文段落/金刚经8分-佛法即非佛法.md","filePath":"60-原文段落/金刚经8分-佛法即非佛法.md","lastUpdated":null}'),_={name:"60-原文段落/金刚经8分-佛法即非佛法.md"};function p(s,t,n,u,c,l){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="金刚经8分-佛法即非佛法" tabindex="-1">金刚经8分-佛法即非佛法 <a class="header-anchor" href="#金刚经8分-佛法即非佛法" aria-label="Permalink to &quot;金刚经8分-佛法即非佛法&quot;">​</a></h1><blockquote><p>来源：<a href="/01-Raw-Sources/8了空居士讲《金刚经》-第八分依法出生分20161021">8了空居士讲《金刚经》-第八分依法出生分20161021</a> 切分日期：2026-05-06</p></blockquote><hr><p><strong>须菩提！所谓佛法者，即非佛法。</strong></p><p>世尊圆满智慧，他怕我们执着&quot;一切诸佛及诸佛阿耨多罗三藐三菩提法&quot;，这么多法，原来佛祖还有这么多法，皆从此经出，从中变化出种种的法，以最清净的心去对机起用，设种种的方便。哇！这些都是佛法。佛祖说不是，所谓佛法者，即非佛法，说我一生啊设种种方便，对不同人讲不同的方便，种种的法。这些呀，你们不能执着，我是针对性而起用，这个问题解决了，这个人开悟了，也许这个方法对别的人也不一定适合的，所以你们不要以为佛法就是我所说的种种方便，就是佛法。不是！不是！真正悟到佛法的人就是悟到这种空理，明心见性，然后针对性地给大家设种种方便，你不能再搬我原来对别人说的方法再去给别人用，那就不一定恰当了。不要以为我说的那就是佛法，然后你们继续搬过去，搬来搬去的用，那就不对了。其实我千经万论是围绕了使你们证悟这种&quot;性&quot;，这种自性，这才是最重要的。证悟自性之后，你们就从自性的起用，因材施教，就能够跟我佛祖一样设种种的方便，去度众生了。</p><hr><p><strong>真正的佛法就是缘起性空这个总规律</strong></p><p>所谓佛法者即非佛法，是不是能说出来的佛法不是真正的佛法，真正的佛法是无法用语言表达出来的？不对，不对，&quot;无有定法名阿耨多罗三藐三菩提&quot;、&quot;无有定法如来可说&quot;。</p><p>其实真正的佛法是什么？就是缘起性空这个总规律啊。缘起性空，我只能说缘起性空，要不然我就要举例子，用一个具体的运用，否则这个缘起性空怎么都抓不出来的。所以说出来的已经是以缘起性空之理去具体问题具体运用了。</p><p>所谓佛法就是你要以智慧的眼光去看待一切，以智慧的想法去处理一切事情，而不是具体有一个东西可以搬过去用。当然有时碰巧那个事情是一致的，你照搬也可以，如果是不一致的，你还是要改一下吧。就是用这种整体观、用这种清净心来具体问题具体分析，这就是佛法。</p>',10)])])}const q=o(_,[["render",p]]);export{i as __pageData,q as default};
